#include "encore/battle_action_presentation.hpp"
#include <iostream>
using namespace encore::upstream;
int main(int argc,char**argv){if(argc!=3)return 2;BattleRoundData round;BattleData entry;std::string error;if(!round.load_file(argv[1],error)||!entry.load_file(argv[2],error)){std::cerr<<error;return 1;}SourceRandom random(725);BattleActionPresentation p;if(!p.begin(round.view(),entry.view(),random))return 1;BattleRoundCue cue;cue.kind=BattleRoundCueKind::Defeat;cue.target=1;if(!p.emit(cue,random))return 1;unsigned flash=0,hidden=0,killed=0,done=0;const double dt=double(float(1./60));for(unsigned i=1;i<601;++i){if(!p.physics_frame(dt)||!p.idle_frame(dt))return 1;for(auto&o:p.overlays())if(o.role==uint32_t(RoundMediaRole::BossFlash)&&!flash)flash=i;if(!p.actor_pose(1).visible&&!hidden)hidden=i;if(!p.enemies_visible()&&!killed)killed=i;if(p.ready(BattleRoundGate::BossDefeatDone,1)){done=i;break;}}std::cout<<"{\"flash_started\":"<<flash<<",\"enemy_hidden\":"<<hidden<<",\"defeat_enemies\":"<<killed<<",\"victory_requested\":"<<done<<",\"next_randi\":\""<<random.randi()<<"\"}\n";}
